using System.Reflection;
using ByteEngine.Core.Gameplay;
using ByteEngine.Core.Scene;
using KarlsonDemo.Plugin;
static class MiningResearchTests
{
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS research: "+s);}
 static void Set(object o,string p,object v)=>o.GetType().GetProperty(p)!.SetValue(o,v);
 public static void Run()
 {
  var scene=new Scene("Research tests");var player=scene.CreateGameObject("Player");var hp=player.AddComponent(new HealthComponent());var dash=player.AddComponent(new DashAbility3D());var energy=player.AddComponent(new ResourceMeter3D());energy.Reset();var weapon=scene.CreateGameObject("Gun").AddComponent(new WeaponDefinition3D{DamagePerPellet=20});var co=scene.CreateGameObject("Company");var op=co.AddComponent(new MiningOperation3D{PlayerObjectId=player.Id,StartingCredits=10000,PersistProgress=false});op.Initialize();var trade=co.AddComponent(new MiningTrade3D{OperationObjectId=co.Id,PersistProgress=false});trade.Initialize();
  int credits=op.Credits;Check(!trade.BuyResearch("arms2")&&op.Credits==credits,"locked nodes do not spend credits");Check(trade.BuyResearch("company")&&Math.Abs(weapon.DamagePerPellet-21)<.001f,"charter actually improves weapon damage");credits=op.Credits;Check(!trade.BuyResearch("company")&&op.Credits==credits,"permanent nodes cannot be purchased twice");Check(trade.BuyResearch("arms1")&&Math.Abs(weapon.DamagePerPellet-22.6f)<.001f,"damage bonuses add without multiplying repeatedly");
  Check(trade.BuyResearch("industry1")&&op.PermanentExtractionBonus==.1f,"industrial research changes extraction bonus");Check(trade.BuyResearch("industry2")&&Math.Abs(op.RefineryYieldMultiplier-1.15f)<.001f,"ore recovery changes real refinery yield");Check(trade.BuyResearch("survival1")&&hp.MaxHealth==115,"medicine changes maximum health");Check(trade.BuyResearch("survival2")&&energy.Capacity==100&&hp.MaxHealth==140,"trauma plating replaces unused energy upgrades with real health");Check(!trade.BuyResearch("arms3"),"cross-branch upgrade still requires its weapon prerequisite");Check(trade.BuyResearch("arms2")&&trade.BuyResearch("arms3")&&trade.Output==3.75f,"supply network changes actual ammo production after both prerequisites");
  Set(op,"RawOre",20);float oldDuration=op.RefineryDuration;Check(op.Buy(MiningUpgrade.RefinerySpeed)&&op.RefineryDuration<oldDuration&&op.RefineryLevel==0,"processing speed is independent of batch size");Check(op.Buy(MiningUpgrade.RefineryYield)&&Math.Abs(op.RefineryYieldMultiplier-1.25f)<.001f,"refinery recovery stacks with company research");Check(op.BeginRefining()&&op.RefiningOutput==25,"batch locks its real output at processing start");op.Tick(100);Check(op.RawOre==0&&op.RefinedOre==25,"upgraded refinery conserves input and pays the promised output");
  Check(Math.Abs(weapon.ReloadSeconds-1.6f/1.35f)<.001f&&weapon.MagazineCapacity==21,"feed upgrades change real reload time and magazine capacity without stacking repeatedly");
  Check(Math.Abs(dash.Cooldown-1.25f)<.001f,"health branch no longer changes the disabled dash ability");Check(trade.AutomaticRefining&&trade.AutomaticAmmoDelivery,"automation is unlocked by its prerequisite branches");
  Set(op,"RawOre",8);trade.Tick(.1f);Check(op.RefiningAmount==8,"automation starts a real refinery batch without clicking");
  var ui=scene.CreateGameObject("UI").AddComponent(new MiningBusinessUi3D{OperationObjectId=co.Id,WorkshopObjectId=co.Id});ui.Open(MiningScreen.Company);Check(ui.Screen==MiningScreen.None,"company access rejects a missing or remote tent");var tent=scene.CreateGameObject("Tent");ui.TerminalObjectId=tent.Id;ui.Open(MiningScreen.Company);Check(ui.Screen==MiningScreen.Research,"nearby tent opens upgrades directly");ui.Close();player.Transform.WorldPosition=new(100,0,100);ui.Open(MiningScreen.Market);Check(ui.Screen==MiningScreen.None,"market cannot be opened remotely");
  string root=Path.Combine(Path.GetTempPath(),"MiningResearch-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);typeof(Scene).GetProperty("ProjectRoot")!.SetValue(scene,root);trade.PersistProgress=true;trade.Save();var fresh=new Scene("Reload");typeof(Scene).GetProperty("ProjectRoot")!.SetValue(fresh,root);var freshCo=fresh.CreateGameObject("Company");freshCo.AddComponent(new MiningOperation3D{PersistProgress=false});var loaded=freshCo.AddComponent(new MiningTrade3D{OperationObjectId=freshCo.Id});loaded.Initialize();Check(loaded.HasResearch("company")&&loaded.HasResearch("industry2")&&loaded.HasResearch("arms3"),"permanent research ownership survives a fresh scene");
 }
}
